package com.tripmateai.security; import com.fasterxml.jackson.databind.ObjectMapper; import org.springframework.beans.factory.annotation.Value; import org.springframework.stereotype.Service; import javax.crypto.Mac; import javax.crypto.spec.SecretKeySpec; import java.nio.charset.StandardCharsets; import java.time.Instant; import java.util.*; @Service public class JwtService { private final ObjectMapper mapper; private final String secret; public JwtService(ObjectMapper mapper,@Value("${app.jwt.secret:change-this-development-secret-key-to-at-least-32-characters}")String secret){this.mapper=mapper;this.secret=secret;} public String generate(String email,long seconds){try{var h=b64("{\"alg\":\"HS256\",\"typ\":\"JWT\"}");var p=b64(mapper.writeValueAsString(Map.of("sub",email,"iat",Instant.now().getEpochSecond(),"exp",Instant.now().plusSeconds(seconds).getEpochSecond())));return h+"."+p+"."+sign(h+"."+p);}catch(Exception e){throw new IllegalStateException(e);}} public String subject(String token){try{var p=mapper.readValue(Base64.getUrlDecoder().decode(token.split("\\.")[1]),Map.class);if(((Number)p.get("exp")).longValue()<Instant.now().getEpochSecond())throw new IllegalArgumentException("Token expired");return (String)p.get("sub");}catch(Exception e){throw new IllegalArgumentException("Invalid token",e);}} public boolean valid(String t){try{var x=t.lastIndexOf('.');return sign(t.substring(0,x)).equals(t.substring(x+1))&&subject(t)!=null;}catch(Exception e){return false;}} private String sign(String s){try{var m=Mac.getInstance("HmacSHA256");m.init(new SecretKeySpec(secret.getBytes(StandardCharsets.UTF_8),"HmacSHA256"));return Base64.getUrlEncoder().withoutPadding().encodeToString(m.doFinal(s.getBytes(StandardCharsets.UTF_8)));}catch(Exception e){throw new IllegalStateException(e);}} private String b64(String v){return Base64.getUrlEncoder().withoutPadding().encodeToString(v.getBytes(StandardCharsets.UTF_8));}}
